void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Common sizes (N, M)
	const std::size_t n_len = C | get_length<'i'>(); // N
	// (M is not needed explicitly here)

#pragma scop
	// -------------------------------------------------------------------------
	// 1) Scale the lower-triangular part of C by beta.
	//
	// Original:
	//   for (i = 0; i < N; i++)
	//     for (j = 0; j <= i; j++)
	//       C[i][j] *= beta;
	//
	// Reordered to (j outer, i inner):
	//   for (j = 0; j < N; j++)
	//     for (i = j; i < N; i++)
	//       C[i][j] *= beta;
