	// but iterates i as the innermost dimension, improving spatial locality
	// when i is the inner (fastest) physical dimension.
	// -------------------------------------------------------------------------
	traverser(C).template for_dims<'j'>([=](auto trav_j) {
		// trav_j has 'j' fixed, 'i' remaining
		auto state_j = trav_j.state();
		const std::size_t j_idx = get_index<'j'>(state_j);

		// Restrict i to [j_idx, n_len) so that we only touch j <= i
		auto trav_ji = trav_j.order(noarr::slice<'i'>(j_idx, n_len - j_idx));

		// Now for_each iterates only over the valid (i >= j) part
		trav_ji.for_each([=](auto state) {
			// state has indices (i, j)
			C[state] *= beta;
		});
	});

	// -------------------------------------------------------------------------
	// 2) Rank-2k update:
	//
	// Original Polybench-like form:
	//   for (i = 0; i < N; i++)
	//     for (k = 0; k < M; k++)
	//       for (j = 0; j <= i; j++)
	//         C[i][j] += alpha * A[i][k] * B[j][k]
	//                   + alpha * B[i][k] * A[j][k];
	//
