	//   for (j = 0; j < N; j++)
	//     for (k = 0; k < M; k++) {
	//       Ajk = A[j][k];
	//       Bjk = B[j][k];
	//       for (i = j; i < N; i++)
	//         C[i][j] += alpha * A[i][k] * Bjk
	//                   + alpha * B[i][k] * Ajk;
	//     }
