	//     with unit stride in i.
	//   - A[j][k] and B[j][k] are reused for all i >= j at fixed (j,k).
	// -------------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'j'>([=](auto trav_j) {
		// trav_j has 'j' fixed, 'i' and 'k' remaining
