			auto state_jk = trav_jk.state();

			// Build a state for A/B where i = j (A[j][k], B[j][k]).
			// Note: 'j' is not a dimension of A/B, so it will be ignored
			// there; only the injected index_in<'i'> and 'k' matter.
			auto state_jk_for_AB =
