constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// layout tuning (can be changed independently of the algorithm)
struct tuning {
	// C is N x N, indexed by (i, j)
	// Use layout i (outer) x j (inner) so that C[i][j] with j as the innermost
	// loop is contiguous in memory (better locality for the kernel below).
	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec); // physical layout: i (outer) x j (inner)

	// A is N x M, indexed by (i, k)
	// Keep k (outer) x i (inner) so that, for fixed k, sweeping over i (used
	// for the j-index in the kernel) is contiguous.
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // physical layout: k (outer) x i (inner)

	// B is N x M, indexed by (i, k)
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec); // physical layout: k (outer) x i (inner)
} tuning;

// initialization function
// C: i x j  (N x N)
// A: i x k  (N x M)
// B: i x k  (N x M)
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Precompute lengths once; they are invariant across traversals.
	const auto n_len = A | get_length<'i'>(); // corresponds to original 'n'
	const auto m_len = B | get_length<'k'>(); // corresponds to original 'm'

	// Initialize A: A[i][k] = ( (i * k + 1) % n ) / n
	traverser(A).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// Initialize B: B[i][k] = ( (i * k + 2) % m ) / m
	traverser(B).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		B[state] = (num_t)((i * k + 2) % m_len) / m_len;
	});

	// Initialize C: C[i][j] = ( (i * j + 3) % n ) / m
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 3) % n_len) / m_len;
	});
}

// computation kernel
// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
//
// Optimizations applied:
// - Use two separate traversals for the beta-scaling and the rank-2k update,
//   to keep traversals focused on the structures they actually touch.
// - Restrict the j-loop to the lower-triangular part via noarr::slice instead
//   of an inner if (j <= i) branch. This reduces control divergence and
//   simplifies the innermost loops.
// - Hoist A[i][k] and B[i][k] out of the innermost j-loop so they are loaded
//   once per (i,k) pair and then reused from registers.
// - Keep accesses A[j][k] and B[j][k] contiguous along the inner 'i' dimension
//   by the chosen layout (k_vec ^ i_vec).
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// -------------------------------------------------------------------------
	// First part: C[i][j] = beta * C[i][j] for all 0 <= j <= i < N
	// -------------------------------------------------------------------------
	// Only C is involved here, so use a traverser over C alone to avoid
	// unnecessary iteration over the extra 'k' dimension present in A/B.
#pragma scop
	traverser(C).template for_dims<'i'>([&](auto trav_i) {
		// Fixed index in 'i'
		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// Restrict j to [0, i_idx] using slice; this removes the j <= i branch.
		trav_i
			.order(slice<'j'>(std::size_t(0), i_idx + 1))
			.for_each([&](auto state) {
				// state contains (i, j)
				C[state] *= beta;
			});
	});

	// -------------------------------------------------------------------------
	// Second part:
	//   for (k = 0; k < M; k++)
	//     for (j = 0; j <= i; j++)
	//       C[i][j] += A[j][k] * alpha * B[i][k]
	//                  + B[j][k] * alpha * A[i][k];
	//
	// We implement this as:
	//   for all i
	//     for all k
	//       precompute A[i][k], B[i][k] and their alpha-scaled versions
	//       for j in [0, i] (lower triangle only):
	//         accumulate into C[i][j]
	// -------------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// i is fixed here
		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// Next loop over k (columns of A and B)
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has both 'i' and 'k' fixed; obtain their current state
			auto state_ik = trav_ik.state();

			// Load A[i][k] and B[i][k] once per (i, k) and keep them in registers
			const num_t A_ik = A[state_ik];
			const num_t B_ik = B[state_ik];

			const num_t alpha_A_ik = alpha * A_ik;
			const num_t alpha_B_ik = alpha * B_ik;

